import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

// Books live in memory and are written to a JSON file after every change.
// Writes go through a queue so they never overlap, and each one goes to a
// temp file that is then renamed, so a crash mid-write can't corrupt the file.
export async function createStore(file) {
  const books = await load(file);
  let writes = Promise.resolve();

  function persist() {
    const json = JSON.stringify(books, null, 2) + '\n';
    writes = writes.catch(() => {}).then(() => save(file, json));
    return writes;
  }

  return {
    list() {
      return books.map((b) => ({ ...b }));
    },

    get(id) {
      const book = books.find((b) => b.id === id);
      return book ? { ...book } : undefined;
    },

    async add({ title, author = '', notes = '' }) {
      const book = {
        id: randomBytes(6).toString('base64url'),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await persist();
      return { ...book };
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        await persist();
      }
      return { ...book };
    },
  };
}

async function load(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // A file that won't parse is an error, not an empty list: starting fresh
  // would overwrite the user's books on the next save.
  const data = JSON.parse(text);
  if (!Array.isArray(data)) {
    throw new Error(`${file} should contain a JSON array of books`);
  }
  return data;
}

async function save(file, json) {
  await mkdir(dirname(file), { recursive: true });
  const tmp = `${file}.tmp`;
  await writeFile(tmp, json);
  await rename(tmp, file);
}

