const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value).replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<main>
${body}
</main>
</body>
</html>
`;
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function finishButton(book, next) {
  return `<form method="post" action="/books/${escape(book.id)}/finish" class="inline">
  <input type="hidden" name="next" value="${escape(next)}">
  <button type="submit">Mark as finished</button>
</form>`;
}

function bookItem(book) {
  const author = book.author ? ` <span class="author">by ${escape(book.author)}</span>` : '';
  const action = book.status === 'reading'
    ? finishButton(book, '/')
    : `<span class="meta">Finished ${escape(formatDate(book.finishedAt))}</span>`;
  return `<li>
  <a href="/books/${escape(book.id)}">${escape(book.title)}</a>${author}
  ${action}
</li>`;
}

function bookList(books, empty) {
  if (books.length === 0) return `<p class="empty">${escape(empty)}</p>`;
  return `<ul class="books">\n${books.map(bookItem).join('\n')}\n</ul>`;
}

export function homePage(books, { error = '', values = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout('My books', `
<h1>My books</h1>

<section>
<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}
</section>

<section>
<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}
</section>

<section>
<h2>Add a book</h2>
${error ? `<p class="error" role="alert">${escape(error)}</p>` : ''}
<form method="post" action="/books" class="add">
  <label>Title <input name="title" required maxlength="300" value="${escape(values.title ?? '')}"></label>
  <label>Author <input name="author" maxlength="300" value="${escape(values.author ?? '')}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="10000">${escape(values.notes ?? '')}</textarea></label>
  <button type="submit">Add book</button>
</form>
</section>
`);
}

export function bookPage(book) {
  const status = book.status === 'finished'
    ? `<p class="meta">Finished ${escape(formatDate(book.finishedAt))}</p>`
    : `<p class="meta">Currently reading · started ${escape(formatDate(book.addedAt))}</p>
${finishButton(book, `/books/${book.id}`)}`;

  return layout(book.title, `
<p><a href="/">&larr; All books</a></p>
<h1>${escape(book.title)}</h1>
<p class="author">${book.author ? `by ${escape(book.author)}` : 'Unknown author'}</p>
${status}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="empty">No notes yet.</p>'}
`);
}

export function notFoundPage() {
  return layout('Not found', `
<h1>Not found</h1>
<p>There's no book at this address. <a href="/">Back to all books</a></p>
`);
}

export const stylesheet = `
body { font-family: system-ui, sans-serif; line-height: 1.5; color: #222; background: #fdfcfa; margin: 0; }
main { max-width: 40rem; margin: 0 auto; padding: 1.5rem 1rem 3rem; }
h1 { margin-bottom: 0.25rem; }
h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
