.books { list-style: none; padding: 0; }
.books li { padding: 0.5rem 0; border-bottom: 1px solid #eee; display: flex; flex-wrap: wrap; gap: 0.25rem 0.5rem; align-items: baseline; }
.books li > form, .books li > .meta { margin-left: auto; }
.author, .meta, .empty { color: #666; }
.meta { font-size: 0.9rem; }
.inline { display: inline; }
.notes { white-space: pre-wrap; }
