    const book = store.get(bookMatch[1]);
    if (!book) return sendHtml(res, 404, notFoundPage());
    return sendHtml(res, 200, bookPage(book));
  }

  if (finishMatch && req.method === 'POST') {
    const id = finishMatch[1];
    const form = await readForm(req);
    const book = await store.finish(id);
    if (!book) return sendHtml(res, 404, notFoundPage());
    // Only allow redirects back to pages in this app.
    const next = form.get('next') === `/books/${id}` ? `/books/${id}` : '/';
    return redirect(res, next);
  }

  if (pathname === '/' || pathname === '/books' || pathname === '/style.css' || bookMatch || finishMatch) {
    throw new HttpError(405, 'Method not allowed');
  }
  return sendHtml(res, 404, notFoundPage());
}

function validate(values) {
  if (!values.title) return 'Please give the book a title.';
  for (const [field, max] of Object.entries(LIMITS)) {
    if (values[field].length > max) return `The ${field} is too long (max ${max} characters).`;
  }
  return '';
}

async function readForm(req) {
  const type = req.headers['content-type'] ?? '';
  if (!type.startsWith('application/x-www-form-urlencoded')) {
    throw new HttpError(415, 'Expected a form submission');
  }
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'Form is too large');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function sendHtml(res, status, html) {
  send(res, status, 'text/html; charset=utf-8', html);
}

function send(res, status, type, body) {
  res.writeHead(status, {
    'Content-Type': type,
    'Content-Length': Buffer.byteLength(body),
    'Content-Security-Policy': "default-src 'none'; style-src 'self'; form-action 'self'; frame-ancestors 'none'",
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'same-origin',
  });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

