import { createServer } from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { createStore } from '../src/store.js';

let dir, file, server, base;

async function start() {
  const store = await createStore(file);
  server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields) {
  return fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  const books = JSON.parse(await readFile(file, 'utf8'));
  return books.at(-1);
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'data', 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty sections and the add form on first open', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
    expect(html).toContain('action="/books"');
  });

  it('adds a book, lists it as reading and shows its page', async () => {
    const book = await addBook({ title: 'Middlemarch', author: 'George Eliot', notes: 'Line one\nLine two' });
    expect(book.status).toBe('reading');

    const home = await (await fetch(base + '/')).text();
    const reading = home.slice(home.indexOf('Currently reading'), home.indexOf('<h2>Finished'));
    expect(reading).toContain(`href="/books/${book.id}"`);
    expect(reading).toContain('George Eliot');

    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const page = await res.text();
    expect(page).toContain('<h1>Middlemarch</h1>');
    expect(page).toContain('by George Eliot');
    expect(page).toContain('Line one\nLine two');
  });

  it('marks a book as finished and moves it to the finished list', async () => {
    const book = await addBook({ title: 'Dune' });
    const res = await post(`/books/${book.id}/finish`, { next: '/' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const finished = home.slice(home.indexOf('<h2>Finished'), home.indexOf('<h2>Add a book'));
    expect(finished).toContain('Dune');
    expect(home.slice(0, home.indexOf('<h2>Finished'))).not.toContain('Dune');

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved[0].status).toBe('finished');
    expect(saved[0].finishedAt).toBeTruthy();
  });

  it('redirects back to the book page when finishing from there, but not elsewhere', async () => {
    const book = await addBook({ title: 'Emma' });
    const back = await post(`/books/${book.id}/finish`, { next: `/books/${book.id}` });
    expect(back.headers.get('location')).toBe(`/books/${book.id}`);
    const offsite = await post(`/books/${book.id}/finish`, { next: 'https://evil.example' });
    expect(offsite.headers.get('location')).toBe('/');
  });

  it('keeps books after a restart', async () => {
    const book = await addBook({ title: 'Persuasion', author: 'Jane Austen' });
    await stop();
    await start();
    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).toContain('Persuasion');
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '   ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');
  });

  it('escapes user input in pages', async () => {
    const book = await addBook({ title: '<script>alert(1)</script>', notes: '<img src=x onerror=alert(1)>' });
    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).not.toContain('<script>alert');
    expect(page).not.toContain('<img');
    expect(page).toContain('&lt;script&gt;');
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
    expect((await fetch(`${base}/missing`)).status).toBe(404);
  });

  it('refuses to start over a corrupt data file rather than wiping it', async () => {
    await stop();
    await writeFile(file, '{ not json');
    await expect(createStore(file)).rejects.toThrow();
    expect(await readFile(file, 'utf8')).toBe('{ not json');
    await writeFile(file, '[]');
    await start();
  });
});

